        -H "Content-Type: application/json" \
        -d '{"nome":"Ana","email":"ana@example.com","senha":"123456","telefone":"(11) 99999-8888"}'
   ```

Esta é uma API RESTful completa para gerenciamento de usuários, utilizando **Express** para o backend e **Mongoose** para persistência em **MongoDB**. O código inclui:

- Conexão à base de dados com tratamento de erros.
- Modelo `User` com validações básicas.
- Rotas CRUD (GET, POST, PUT, DELETE) com respostas JSON padronizadas.
- Middleware de CORS e de parse de JSON.
- Utilização de `dotenv` para configurar variáveis de ambiente.

```javascript
// ---------------------------------------------------------------
//  IMPORTS
// ---------------------------------------------------------------
const express      = require('express');          // Framework web
const mongoose     = require('mongoose');         // ORM para MongoDB
const cors         = require('cors');             // CORS middleware
const dotenv       = require('dotenv');           // Carrega variáveis .env
const { validationResult } = require('express-validator'); // Validação (opcional)

// Carrega variáveis de ambiente (arquivo .env na raiz)
dotenv.config();

// ---------------------------------------------------------------
//  CONFIGURAÇÃO DO EXPRESS
// ---------------------------------------------------------------
const app = express();

// Middleware para receber JSON no body
app.use(express.json());

// Habilita CORS (pode ser configurado para origens específicas)
app.use(cors());

// ---------------------------------------------------------------
//  CONEXÃO COM O MONGODB
// ---------------------------------------------------------------
const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017/usuariodb';

mongoose.connect(MONGODB_URI, {
  useNewUrlParser   : true,
  useUnifiedTopology: true,
})
.then(() => console.log('✅ Conectado ao MongoDB'))
.catch(err => {
  console.error('❌ Erro ao conectar ao MongoDB:', err);
  process.exit(1);
});

// ---------------------------------------------------------------
//  MODELO (Schema) - Usuário
// ---------------------------------------------------------------
const userSchema = new mongoose.Schema({
  nome: {
    type: String,
    required: [true, 'O nome é obrigatório'],
    trim: true,
  },
  email: {
    type: String,
    required: [true, 'O e‑mail é obrigatório'],
    unique: true,
    lowercase: true,
    trim: true,
    match: [/^\S+@\S+\.\S+$/, 'E‑mail inválido'],
  },
  senha: {
    type: String,
    required: [true, 'A senha é obrigatória'],
    minlength: 6,
  },
  // Campos opcionais
  telefone: {
    type: String,
    trim: true,
  },
  createdAt: {
    type: Date,
    default: Date.now,
  },
});

// Índice único para e‑mail (já definido com `unique:true` acima)
userSchema.index({ email: 1 }, { unique: true });

// Model exportado
const User = mongoose.model('User', userSchema);

// ---------------------------------------------------------------
//  ROTAS (CRUD) - USUÁRIOS
// ---------------------------------------------------------------

// Helper para resposta de erro padronizada
const respondWithError = (res, err) => {
  const status = err.statusCode || 500;
  res.status(status).json({ error: err.message });
};

// GET /users – lista todos os usuários (pode aceitar query params de paginação)
app.get('/users', async (req, res) => {
  try {
    const limit  = parseInt(req.query.limit)  || 10;
    const skip   = parseInt(req.query.skip)   || 0;
    const users  = await User.find().sort({ createdAt: -1 }).limit(limit).skip(skip);
    res.json(users);
  } catch (err) {
    respondWithError(res, { message: 'Falha ao buscar usuários', statusCode: 500 });
  }
});

// GET /users/:id – detalha um usuário
app.get('/users/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const user = await User.findById(id);
    if (!user) return res.status(404).json({ error: 'Usuário não encontrado' });
    res.json(user);
  } catch (err) {
    respondWithError(res, { message: 'Erro ao obter usuário', statusCode: 500 });
  }
});

// POST /users – cria um novo usuário
app.post(
  '/users',
  async (req, res) => {
    // Validação simples (pode usar express-validator para regras mais robustas)
    const { nome, email, senha, telefone } = req.body;

    // Checa se o e‑mail já existe
    const existente = await User.findOne({ email });
    if (existente) {
      return res.status(400).json({ error: 'E‑mail já cadastrado' });
    }

    const novoUsuario = new User({
      nome,
      email,
      senha,
      telefone,
    });

    try {
      const usuarioSalvo = await novoUsuario.save();
      res.status(201).json(usuarioSalvo);
    } catch (err) {
      // Erros de validação do Mongoose (ex.: email duplicado)
      if (err.code === 11000) {
        return res.status(400).json({ error: 'E‑mail já cadastrado' });
      }
      respondWithError(res, { message: 'Erro ao criar usuário', statusCode: 500 });
    }
  }
);

// PUT /users/:id – atualiza um usuário (partial update)
app.put('/users/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const dadosAtualizados = req.body; // permite atualizar apenas alguns campos

    const usuarioAtualizado = await User.findByIdAndUpdate(
      id,
      dadosAtualizados,
      { new: true, runValidators: true } // devolve o documento atualizado
    );

    if (!usuarioAtualizado) {
      return res.status(404).json({ error: 'Usuário não encontrado' });
    }
    res.json(usuarioAtualizado);
  } catch (err) {
    // Se houver falha de validação (ex.: senha curta)
    if (err.message.includes('validation')) {
      return res.status(400).json({ error: err.message });
    }
    respondWithError(res, { message: 'Erro ao atualizar usuário', statusCode: 500 });
  }
});

// DELETE /users/:id – remove um usuário
app.delete('/users/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const usuarioRemovido = await User.findByIdAndDelete(id);
    if (!usuarioRemovido) {
      return res.status(404).json({ error: 'Usuário não encontrado' });
    }
    res.json({ message: 'Usuário removido com sucesso' });
  } catch (err) {
    respondWithError(res, { message: 'Erro ao excluir usuário', statusCode: 500 });
  }
});

// ---------------------------------------------------------------
//  MIDDLEWARE DE TRATAMENTO DE ERROS GLOBAL (opcional)
// ---------------------------------------------------------------
app.use((err, req, res, next) => {
  console.error('🛑 Erro inesperado:', err);
  respondWithError(res, { message: 'Erro interno do servidor', statusCode: 500 });
});

// ---------------------------------------------------------------
//  INÍCIO DO SERVIDOR
// ---------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 API rodando na porta ${PORT}`);
});
