const express = require('express');
const dcmjs = require('dcmjs');
const sharp = require('sharp');
const fetch = require('node-fetch');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 3000;

/**
 * Middleware to convert a DICOM‑Web request to a legacy image format (PNG) using GPU‑accelerated Sharp.
 * Expected query parameters: studyInstanceUID, seriesInstanceUID, sopInstanceUID.
 */
app.get('/convert', async (req, res) => {
    const { studyInstanceUID, seriesInstanceUID, sopInstanceUID } = req.query;

    if (!studyInstanceUID || !seriesInstanceUID || !sopInstanceUID) {
        return res.status(400).json({ error: 'Missing required DICOM‑Web UID parameters' });
    }

    // Build the Orthanc (or compatible) DICOM‑Web retrieve URL.
    const retrieveUrl = `http://orthanc/instance/study/${studyInstanceUID}/series/${seriesInstanceUID}/object/${sopInstanceUID}`;

    try {
        const response = await fetch(retrieveUrl);
        if (!response.ok) {
            return res.status(502).json({ error: `Failed to fetch DICOM object: ${response.status}` });
        }
        const dicomBuffer = await response.buffer();

        // Parse the DICOM file.
        const dicomData = dcmjs.io.Bufferoche.decode(dicomBuffer);
        const dataset = dcmjs.data.DicomMessage.read(dicomData);

        // Locate Pixel Data (tag 0x7FE0) and basic image geometry.
        const pixelItem = dataset.items.find(i => i.tag === 0x7FE0);
        if (!pixelItem) {
            return res.status(404).json({ error: 'Pixel data not found in DICOM object' });
        }

        const rows = dataset.Rows || 0;
        const cols = dataset.Columns || 0;
        const samplesPerPixel = dataset.BitsAllocated / 8; // bytes per sample
        const pixelRep = dataset.PixelRepresentation || 0; // 0=monochrome, 1=RGB

        // For simplicity, assume little‑endian mono images (most common). Adjust if needed.
        const rawBuffer = pixelItem.value;

        // Use Sharp's .raw() method for GPU‑accelerated decoding/encoding.
        sharp.raw({
            width: cols,
            height: rows,
            channels: samplesPerPixel,
            bitDepth: dataset.BitsAllocated,
        })
            .rotate() // Apply orientation from DICOM tags if required.
            .png()    // Legacy output format (PNG)
            .toBuffer()
            .then(pngBuffer => {
                res.type('image/png').send(pngBuffer);
            })
            .catch(err => {
                console.error('Sharp processing error:', err);
                res.status(500).json({ error: 'Image conversion failed' });
            });
    } catch (err) {
        console.error('Request error:', err);
        res.status(500).json({ error: 'Failed to process request' });
    }
});

app.listen(PORT, () => {
    console.log(`DICOM‑Web to Legacy Gateway listening on port ${PORT}`);
});
