// Dependencies (declare explicitly)
const express = require('express');
const dcmjs = require('dcmjs');
const sharp = require('sharp');

// Create Express app
const app = express();
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));

// Middleware to convert DICOM‑Web request to legacy proprietary format (JPEG)
function dicomToLegacy(req, res, next) {
  // Basic size check to prevent OOM
  const contentLength = parseInt(req.headers['content-length'] || '0', 10);
  if (contentLength > 10 * 1024 * 1024) {
    return res.status(413).json({ error: 'Payload too large' });
  }

  // Ensure request body is a Buffer with raw DICOM data
  let dicomData = req.body;
  if (typeof dicomData !== 'object' || !Buffer.isBuffer(dicomData)) {
    return res.status(400).json({ error: 'Invalid request body' });
  }

  // Parse DICOM dataset using dcmjs
  let dataset;
  try {
    dataset = dcmjs.data.DicomMessage.readFileOfDataset(new Uint8Array(dicomData), {});
  } catch (e) {
    return res.status(400).json({ error: 'Failed to parse DICOM data', details: e.message });
  }

  // Validate required DICOM tags
  if (!dataset.Rows || !dataset.Columns || !dataset.PixelData) {
    return res.status(400).json({ error: 'Incomplete DICOM dataset' });
  }

  const width = dataset.Rows;
  const height = dataset.Columns;
  const samplesPerPixel = dataset.SamplesPerPixel || 1;
  const bitsAllocated = dataset.BitsAllocated || 8;
  const pixelData = dataset.PixelData;

  // Compute row stride for proper raw buffer alignment (4‑byte)
  const bytesPerPixel = Math.ceil(bitsAllocated / 8);
  const rowStride = Math.ceil((width * bytesPerPixel * samplesPerPixel) / 4) * 4;

  // Extract raw pixel buffer (ensure correct byte range)
  const rawBuffer = Buffer.from(pixelData.buffer, pixelData.offset, pixelData.length);
  const expectedLength = width * height * samplesPerPixel * bytesPerPixel;
  if (rawBuffer.length < expectedLength) {
    return res.status(400).json({ error: 'Pixel data length mismatch' });
  }

  // GPU‑accelerated transcoding with Sharp (libvips GPU support if compiled)
  try {
    const transcoded = sharp({
      raw: {
        width,
        height,
        channels: samplesPerPixel,
        stride: rowStride,
        data: rawBuffer
      }
    })
      .rotate() // Apply orientation from DICOM tag (0x0112)
      .toFormat('jpeg', { quality: 90 })
      .toBuffer();

    // Legacy proprietary response headers
    res.setHeader('Content-Type', 'image/jpeg');
    res.setHeader('Content-Disposition', 'inline; filename="legacy_image.jpg"');
    res.send(transcoded);
  } catch (err) {
    console.error('Transcoding error:', err);
    res.status(500).json({ error: 'Transcoding failed', details: err.message });
  }
}

// Route example: POST /convert
app.post('/convert', dicomToLegacy);

// Health check endpoint
app.get('/health', (req, res) => res.json({ status: 'ok' }));

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Gateway middleware listening on port ${PORT}`);
});
