  const samplesPerPixel = dataset.SamplesPerPixel || 1;
  const bitsAllocated = dataset.BitsAllocated || 8;
  const pixelData = dataset.PixelData;

  // Compute row stride for proper raw buffer alignment (4‑byte)
  const bytesPerPixel = Math.ceil(bitsAllocated / 8);
  const rowStride = Math.ceil((width * bytesPerPixel * samplesPerPixel) / 4) * 4;

  // Extract raw pixel buffer (ensure correct byte range)
  const rawBuffer = Buffer.from(pixelData.buffer, pixelData.offset, pixelData.length);
  const expectedLength = width * height * samplesPerPixel * bytesPerPixel;
  if (rawBuffer.length < expectedLength) {
    return res.status(400).json({ error: 'Pixel data length mismatch' });
  }

  // GPU‑accelerated transcoding with Sharp (libvips GPU support if compiled)
  try {
    const transcoded = sharp({
      raw: {
        width,
        height,
        channels: samplesPerPixel,
        stride: rowStride,
        data: rawBuffer
      }
    })
      .rotate() // Apply orientation from DICOM tag (0x0112)
      .toFormat('jpeg', { quality: 90 })
      .toBuffer();

    // Legacy proprietary response headers
    res.setHeader('Content-Type', 'image/jpeg');
    res.setHeader('Content-Disposition', 'inline; filename="legacy_image.jpg"');
    res.send(transcoded);
  } catch (err) {
    console.error('Transcoding error:', err);
    res.status(500).json({ error: 'Transcoding failed', details: err.message });
  }
}

