app.post('/convert', dicomToLegacy);

// Health check endpoint
app.get('/health', (req, res) => res.json({ status: 'ok' }));

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Gateway middleware listening on port ${PORT}`);
});
