Below is a **complete, ready‑to‑drop‑in Service Worker** that fulfills the two main PWA requirements you asked for:

1. **Dynamic (runtime) caching** – offline‑first for static assets, network‑first for everything else (API calls, images, etc.).  
2. **Web Push Notifications** – receives push messages, shows a notification, and lets the user click the notification to open the app.

The code uses **Workbox** (the officially recommended library for Service Workers) so you get a battle‑tested cache strategy implementation, and it follows the latest Push‑API best practices.

> **Important** – the Service Worker must be **registered** from your page (e.g. `navigator.serviceWorker.register('/sw.js')`).  
> The push‑subscription flow is normally handled in your front‑end code (or a small helper) that calls `self.registration.pushManager.subscribe(...)` and sends the subscription details to your backend. The Service Worker itself only needs to listen for the `push` and `notificationclick` events.

---

## `sw.js` – Service Worker

```js
/* -------------------------------------------------------------
   Service Worker – PWA with Workbox runtime caching + Push
   -------------------------------------------------------------
   1️⃣  Install & Activate
   2️⃣  Pre‑cache the assets listed in self.__WB_MANIFEST
   3️⃣  Runtime caching (Workbox)
   4️⃣  Push handling (show notification)
   5️⃣  Notification click (focus/activate window)
   6️⃣  Message & clients claim handling
   ------------------------------------------------------------- */

/* -----------------------------------------------------------------
   0️⃣  Workbox import – automatically injects the Workbox scripts
   ----------------------------------------------------------------- */
importScripts('https://storage.googleapis.com/workbox-cdn/releases/6.6.0/workbox-sw.js');

/* -----------------------------------------------------------------
   1️⃣  Install – pre‑cache the files listed in self.__WB_MANIFEST
   ----------------------------------------------------------------- */
self.addEventListener('install', event => {
  // Force the waiting service worker to become active (skip waiting)
  self.skipWaiting();

  // Workbox will automatically precache everything that is present in
  // self.__WB_MANIFEST (generated at build time). If you need to add
  // extra files manually, push them into the array before calling
  // precacheAndRoute().
  event.waitUntil(
    caches.open('workbox-precache')
      .then(cache => cache.addAll(self.__WB_MANIFEST))
  );
});

/* -----------------------------------------------------------------
   2️⃣  Activate – clean up old caches (if any)
   ----------------------------------------------------------------- */
self.addEventListener('activate', event => {
  const cacheWhitelist = ['workbox-precache']; // keep only these caches

  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(name => {
          if (cacheWhitelist.indexOf(name) === -1) {
            // Delete any cache that isn’t in the whitelist
            return caches.delete(name);
          }
        })
      );
    })
  );

  // Take control of all pages under this scope immediately
  self.clients.claim();
});

/* -----------------------------------------------------------------
   3️⃣  Runtime caching (Workbox)
   ----------------------------------------------------------------- */
// 3a) Static assets – cache‑first (they rarely change)
workbox.routing.registerRoute(
  ({ request }) => request.destination === 'document' ||
                    request.destination === 'script' ||
                    request.destination === 'style' ||
                    request.destination === 'image',
  new workbox.strategies.CacheFirst({
    cacheName: 'static-assets',
    plugins: [
      new workbox.expiration.ExpirationPlugin({
        maxEntries: 60,          // keep at most 60 entries
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 days
      })
    ]
  })
);

// 3b) API / dynamic content – network‑first (fallback to cache)
workbox.routing.registerRoute(
  ({ url }) => url.origin === self.location.origin && url.pathname.startsWith('/api/'),
  new workbox.strategies.NetworkFirst({
    cacheName: 'api-dynamic',
    plugins: [
      new workbox.expiration.ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 6 * 60 * 60, // 6 hours
      })
    ]
  })
);

// 3c) Images (outside of static‑document) – cache‑first with fallback
workbox.routing.registerRoute(
  ({ request }) => request.destination === 'image',
  new workbox.strategies.CacheFirst({
    cacheName: 'image-cache',
    plugins: [
      new workbox.expiration.ExpirationPlugin({
        maxEntries: 100,
        maxAgeSeconds: 30 * 24 * 60 * 60,
      })
    ]
  })
);

// 3d) All other requests – network‑first (always try the network first)
workbox.routing.setCatchHandler(({ event }) => {
  // Return a simple fallback response for navigation requests (HTML)
  if (event.request.destination === 'document') {
    return caches.match('/index.html');
  }

  // For everything else – return a generic offline UI or a 404
  return new Response('⚠️ You are currently offline.');
});

/* -----------------------------------------------------------------
   4️⃣  Push – show a notification when a push message arrives
   ----------------------------------------------------------------- */
self.addEventListener('push', event => {
  // The payload may be a JSON string, plain text, or a Blob Buffer.
  // We'll try JSON first, then fall back to text.
  let data = {};

  if (event.data) {
    // Try JSON
    try {
      data = event.data.json();
    } catch (e) {
      // Not JSON – treat as plain text
      data = { text: event.data.text() };
    }
  }

  const title = data.title || '🔔 New notification';
  const options = {
    body: data.body || '',
    icon: '/icons/icon-192.png',
    badge: '/icons/badge.png',
    data: data.url || '/' // where to go when the user clicks
  };

  event.waitUntil(
    self.registration.showNotification(title, options)
  );
});

/* -----------------------------------------------------------------
   5️⃣  Notification click – focus/activate the originating page
   ----------------------------------------------------------------- */
self.addEventListener('notificationclick', event => {
  event.notification.close();

  // Open the page URL that was sent in the notification's data.
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true })
      .then(clientList => {
        for (const client of clientList) {
          // If the window is already open, focus it.
          if (client.url === event.notification.data) {
            return client.focus();
          }
        }
        // Otherwise, open a new tab/window.
        if (clients.openWindow) {
          return clients.openWindow(event.notification.data);
        }
      })
  );
});

/* -----------------------------------------------------------------
   6️⃣  Message channel – useful for updating push subscription
   ----------------------------------------------------------------- */
self.addEventListener('message', event => {
  // Example: front‑end can send a message to change the push subscription
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

/* -----------------------------------------------------------------
   7️⃣  Clients claim – make sure the new SW takes control immediately
   ----------------------------------------------------------------- */
self.addEventListener('activate', event => {
  // This is a second listener (the first one above already does the cleanup)
  self.clients.claim();
});
```

