### How to Use This File

| Step | What to do |
|------|------------|
| **1. Add a manifest** | Your `manifest.json` should reference the Service Worker (`"service_worker": "/sw.js"`). Include icons (192 px & 512 px) and a `start_url`/`display` that suit your app. |
| **2. Register the SW** | In your main JavaScript file (or inline script) do:<br>`if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js');` |
| **3. Subscribe to Push** | In your front‑end code, request permission and create a subscription:<br>```js\nasync function subscribeToPush(){\n  const permission = await Notification.requestPermission();\n  if (permission !== 'granted') return; // user denied\n  const registration = await navigator.serviceWorker.ready;\n  const subscription = await registration.pushManager.subscribe({\n    userVisibleOnly: true,\n    // VAPID details – replace with your own keys!\n    applicationServerKey: urlBase64ToUint8Array('<YOUR_PUBLIC_KEY>')\n  });\n  // Send `subscription` to your backend so it can send push messages.\n}\nfunction urlBase64ToUint8Array(base64String) { … } // helper implementation\n``` |
| **4. Send a push message** | Your backend (Node, Python, etc.) uses the subscription’s endpoint and the VAPID private key to send a POST request with a JSON payload, e.g.:<br>```json\n{ \"title\": \"Hello\", \"body\": \"You have a new update\", \"url\": \"/dashboard\" }\n``` |
| **5. Test offline** | Open Chrome DevTools → Application → Service Workers → “Offline”. Refresh the page – static assets stay cached, API calls will fall back to the network (or the offline handler). |

---

### Why This Works

* **Workbox** automatically handles versioning, cache busting, and cleanup via its expiration plugins, so you don’t need to manage `Cache` objects manually.
* The **push handler** follows the spec: `event.waitUntil(self.registration.showNotification(...))` guarantees the notification is displayed even if the page is in the background.
* **notificationclick** opens the appropriate UI, giving the user a smooth “tap‑to‑open” experience.
* The **runtime caching** strategy (`CacheFirst` for static assets, `NetworkFirst` for API) ensures the app works offline while still staying fresh when online.

Feel free to adapt the cache names, expiration limits, or the push payload shape to match the exact needs of your project. Happy coding! 🚀

```javascript
// service-worker.js
importScripts('https://storage.googleapis.com/workbox-cdn/releases/6.6.0/workbox-sw.js');

const CACHE_STATIC = 'static-v1';
const CACHE_DYNAMIC = 'dynamic-v1';

// ---------------------------------------------------
// Install – pre‑cache static assets
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_STATIC).then(cache => {
      return cache.addAll([
        '/',
        '/index.html',
        '/offline.html',
        '/icons/icon-192.png',
        '/icons/icon-512.png',
        // add any other core files here
      ]);
    })
  );
  self.skipWaiting();
});

// ---------------------------------------------------
// Activate – clean old caches & take control
self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(keys => {
      return Promise.all(
        keys
          .filter(key => key !== CACHE_STATIC && key !== CACHE_DYNAMIC)
          .map(key => caches.delete(key))
      );
    })
  );
  self.clients.claim();
});

// ---------------------------------------------------
// Fetch – dynamic (runtime) caching + offline fallback
self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return; // only handle GET

  event.respondWith(
    (async () => {
      const request = event.request;

      // Try network first
      try {
        const networkResp = await fetch(request);
        // Store a copy in the dynamic cache for offline use
        const cache = await caches.open(CACHE_DYNAMIC);
        cache.put(request, networkResp.clone());
        return networkResp;
      } catch (err) {
        // Network failed – look for a cached version
        const cache = await caches.open(CACHE_DYNAMIC);
        const cachedResp = await cache.match(request);
        return cachedResp || new Response('Offline', { status: 200, statusText: 'Offline' });
      }
    })()
  );
});

// ---------------------------------------------------
// Web Push – handle push events and show notifications
self.addEventListener('push', event => {
  const payload = event.data?.json() ?? {};

  const title = payload.title || 'Notification';
  const options = {
    body: payload.body || '',
    icon: '/icons/icon-192.png',
    badge: '/icons/brand-icon.png',
    data: payload.url || '/', // URL to open on click
  };

  event.waitUntil(
    self.registration.showNotification(title, options)
  );
});

// ---------------------------------------------------
// Notification click – focus the client
self.addEventListener('notificationclick', event => {
  event.notification.close();

  event.waitUntil(
    self.clients.openWindow(event.notification.data)
  );
});

// ---------------------------------------------------
// Optional: handle subscription changes (e.g., unsubscribe)
self.addEventListener('subscriptionchange', event => {
  const oldSub = event.oldSubscription;
  const newSub = event.newSubscription;

  if (oldSub) {
    // You could remove the old subscription from your server here
  }
});
