```javascript
/* eslint-disable no-restricted-globals */
// Workbox (runtime caching) ----------------------------------------------------
importScripts('https://unpkg.com/workbox@6.6.0/workbox-sw.js');

// Web Push (subscription handling) --------------------------------------------
importScripts('https://cdn.jsdelivr.net/npm/web-push@1.0.0/dist/web-push-esm.min.js');

const VAPID_PUBLIC_KEY = 'YOUR_VAPID_PUBLIC_KEY_HERE'; // <-- replace with real key

function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - base64String.length % 4) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const raw = atob(base64);
  const arr = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) arr[i] = raw.charCodeAt(i);
  return arr;
}

self.addEventListener('install', (event) => {
  self.skipWaiting();

  event.waitUntil(
    (async () => {
      // 1️⃣ Subscribe to push (user visible only)
      const sub = await self.registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
      });

      // Here you would normally send `sub` to your backend to register it.
      // For demo purposes we just log it.
      console.log('Push subscription registered', sub);

      // 2️⃣ Pre‑cache static assets (offline support)
      const staticCache = await caches.open('static-cache');
      await staticCache.addAll([
        '/',
        '/index.html',
        '/main.js',
        '/style.css',
        '/icon.png',
        '/badge.png',
      ]);
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Delete old caches
      const keys = await caches.keys();
      await Promise.all(
        keys.map((key) => {
          if (key !== 'static-cache') return caches.delete(key);
        })
      );
      // Take control of all pages
      self.clients.claim();
    })()
  );
});

self.addEventListener('fetch', (event) => {
  // Only handle GET requests
  if (event.request.method !== 'GET') return;

  event.respondWith(
    (async () => {
      const cache = await caches.open('static-cache');
      const cached = await cache.match(event.request);
      if (cached) return cached; // ✅ Return cached response

      try {
        // 🌐 Try network first
        return await fetch(event.request);
      } catch (_) {
        // ❌ Network failed → fallback to offline page
        const offline = await caches.match('/offline.html');
        return offline || new Response('You are offline.');
      }
    })()
  );
});

self.addEventListener('push', (event) => {
  // Extract payload (assumes JSON)
  let payload = {};
  if (event.data) {
    const contentType = event.data.type;
    if (contentType === 'application/json') {
      payload = event.data.json();
    } else {
      payload = { data: event.data };
    }
  }

  const title = payload.title || 'New Notification';
  const body = payload.body || '';
  const url = payload.url || '/';

  const notificationOptions = {
    title,
    body,
    icon: '/icon.png',
    badge: '/badge.png',
    data: { url },
    actions: [{ action: 'open', title: 'Open' }],
  };

  event.waitUntil(
    self.registration.showNotification(title, notificationOptions)
