const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');

function generateHtmlFromJson(data) {
  if (!Array.isArray(data) || data.length === 0) {
    return '<html><body>No data to display</body></html>';
  }

  const headers = Object.keys(data[0]);
  let tableHtml = '<table><tr>';

  headers.forEach(header => {
    tableHtml += `<th style="background-color: #f2f2f2; padding: 10px; text-align: left;">${header}</th>`;
  });
  tableHtml += '</tr>';

  data.forEach(item => {
    tableHtml += '<tr>';
    headers.forEach(header => {
      tableHtml += `<td style="padding: 8px; border-bottom: 1px solid #ccc;">${item[header]}</td>`;
    });
    tableHtml += '</tr>';
  });

  tableHtml += '</table>';

  return `
<!DOCTYPE html>
<html>
<head>
  <style>
    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      margin: 20px;
      color: #333;
    }
    .page-header {
      text-align: center;
      margin-bottom: 20px;
      font-size: 24px;
      font-weight: bold;
      color: #2c3e50;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      margin: 20px 0;
      box-shadow: 0 2px 5px rgba(0,0,0,0.1);
    }
    th, td {
      padding: 12px 15px;
      text-align: left;
      border-bottom: 1px solid #ddd;
    }
    th {
      background-color: #e8f4fc;
      font-weight: 600;
    }
    tr:hover {
      background-color: #f5f9ff;
    }
    .page-footer {
      text-align: center;
      margin-top: 30px;
      color: #7f8c8d;
      font-size: 12px;
    }
  </style>
</head>
<body>
  <div class="page-header">Documento Convertido</div>
  ${tableHtml}
  <div class="page-footer">Gerado com Node.js e Puppeteer</div>
</body>
</html>
  `;
}

(async () => {
  const inputFile = process.argv[2];
  if (!inputFile) {
    console.error('Erro: Por favor, forneça um caminho para o arquivo de entrada (HTML ou JSON)');
