#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');
const { json2pdf } = require('json2pdf');

async function htmlToPdf(htmlPath, pdfPath) {
  const html = fs.readFileSync(htmlPath, 'utf8');
  const browser = await puppeteer.launch({ headless: true });
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'networkidle0' });
  await page.pdf({
    path: pdfPath,
    format: 'A4',
    printBackground: true,
  });
  await browser.close();
}

function jsonToPdf(jsonPath, pdfPath) {
  const jsonData = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));

  const definition = {
    pageSize: 'A4',
    pageMargins: [40, 60, 40, 60],
    content: [
      { text: 'PDF generated from JSON', style: 'header' },
      {
        table: {
          headers: Object.keys(jsonData),
          rows: [Object.values(jsonData)],
        },
      },
    ],
    styles: {
      header: {
        fontSize: 20,
        bold: true,
      },
    },
  };

  json2pdf(definition, pdfPath);
}

(async () => {
  const [, , inputPath, outputPath] = process.argv;
  if (!inputPath || !outputPath) {
    console.error('Usage: node convert.js <input.html|input.json> <output.pdf>');
    process.exit(1);
  }

  const ext = path.extname(inputPath).toLowerCase();
  try {
    if (ext === '.html') {
      await htmlToPdf(inputPath, outputPath);
    } else if (ext === '.json') {
      await jsonToPdf(inputPath, outputPath);
    } else {
      throw new Error('Unsupported file type. Use .html or .json');
    }
    console.log(`PDF generated successfully at ${outputPath}`);
  } catch (err) {
    console.error('Error:', err.message);
    process.exit(1);
  }
})();
