      headers.forEach(h => (html += `<td>${row[h] ?? ''}</td>`));
      html += `</tr>`;
    });
    html += `</table>`;
  } else {
    html += `<table><tr><th>Key</th><th>Value</th></tr>`;
    for (const [k, v] of Object.entries(data)) {
      html += `<tr><td>${k}</td><td>${v}</td></tr>`;
    }
    html += `</table>`;
  }

  html += `</body></html>`;

  const browser = await puppeteer.launch({ headless: true });
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'networkidle0' });
  await page.pdf({ path: pdfPath, format: 'A4' });
  await browser.close();
}

async function main() {
  const [, , inputPath] = process.argv;
  if (!inputPath) {
    console.error('Usage: node convert.js <input.html|input.json>');
    process.exit(1);
  }

  const ext = path.extname(inputPath).toLowerCase();
  const pdfPath = path.resolve(inputPath.replace(ext, '.pdf'));

  try {
    if (ext === '.html') {
      await htmlToPdf(inputPath, pdfPath);
    } else if (ext === '.json') {
      await jsonToPdf(inputPath, pdfPath);
    } else {
      console.error('Unsupported file type. Use .html or .json');
      process.exit(1);
    }
    console.log(`PDF created: ${pdfPath}`);
  } catch (err) {
    console.error('Error:', err);
    process.exit(1);
  }
}

main();
